VERSION='independent-visible-spots-area-density-v1'
GROUPS={
 'forehead':('额头','眉间'),
 'nose':('鼻部',),
 'left_cheek':('画面左鼻旁','画面左颧部','画面左面颊'),
 'right_cheek':('画面右鼻旁','画面右颧部','画面右面颊'),
