LABELS={'full_face':'全面部','forehead':'额部（含眉间）','nose':'鼻部','left_cheek':'画面左面颊（含颧部、鼻旁）','right_cheek':'画面右面颊（含颧部、鼻旁）','perioral':'口周','chin':'下巴及下颌'}
