"""Real worker execution for two fixed triplets; explicit diagnostic contract."""
from pathlib import Path
import os,sys,json,subprocess,time
ROOT=Path(__file__).resolve().parents[1];RUNTIME=ROOT/'runtime/bisenet_celery_v1'
INPUT=ROOT.parents[1].parent/'参赛完整源码提交_20260915/02_水光三项三视图服务/examples'
RUNTIME.mkdir(parents=True,exist_ok=True)
os.environ.update(SHUIGUANG_INPUT_ROOT=str(INPUT),SHUIGUANG_RUNTIME_ROOT=str(RUNTIME),SHUIGUANG_CLOUD_DEVICE='cuda:0',SHUIGUANG_PREPROCESS_MODE='bisenet_rgb_diagnostic_v1',SHUIGUANG_FACE_PARSER_MODEL=str(ROOT/'hair_repair_research/official_assets/face_parsing_resnet18.onnx'),SHUIGUANG_BROKER_URL='filesystem://',SHUIGUANG_RESULT_BACKEND='file://'+str(RUNTIME/'backend'),PYTHONDONTWRITEBYTECODE='1')
sys.path.insert(0,str(ROOT))
from cloud_three.tasks import app
from cloud_three.public_scores import ScoreResponse
def main():
 log=(RUNTIME/'worker.log').open('w');worker=subprocess.Popen([sys.executable,'-m','celery','-A','cloud_three.tasks:app','worker','--pool=solo','--concurrency=1','-Q','shuiguang_diagnostic,shuiguang_scores','--loglevel=INFO','--hostname=bisenet-diagnostic@%h'],cwd=ROOT,env=os.environ,stdout=log,stderr=subprocess.STDOUT)
 checks=[]
 try:
  for sample in ('one','two'):
   request={'task_id':'bisenet_'+sample,'images':[{'image_id':v,'path':f'{sample}/inputs/{v}.jpg'} for v in ('right','front','left')],'mirrored':False}
   began=time.monotonic();r=app.send_task('shuiguang.analyze_three_views_diagnostic',args=[request],queue='shuiguang_diagnostic').get(timeout=300,interval=1)
   assert r.get('schema_version')=='shuiguang_diagnostic_v1',r
   assert r['reference_matches_new_preprocessing'] is False;ScoreResponse.model_validate(r['scores'])
   expected=json.loads((ROOT/'runtime/bisenet_deployment/score_comparison_v2'/f'{sample}.json').read_text())['after']['scores']
   assert r['scores']==expected,'Celery scores differ from saved-evidence comparison'
   job=RUNTIME/'diagnostic_jobs'/request['task_id'];timing=json.loads((job/'resident_timing.json').read_text());trace=json.loads((job/'scoring_evidence_trace.json').read_text())
   assert timing['algorithms']==['pores','spots','surface_gloss'] and timing['services']==['dermavision']
   assert set(trace['doctor_pipeline_projects'])=={'rgb','pores','surface_gloss'}
   repeat=app.send_task('shuiguang.analyze_three_views_diagnostic',args=[request],queue='shuiguang_diagnostic').get(timeout=30,interval=1);assert repeat==r
   conflict={**request,'images':list(reversed(request['images']))}
   failed=app.send_task('shuiguang.analyze_three_views_diagnostic',args=[conflict],queue='shuiguang_diagnostic').get(timeout=30,interval=1);assert failed['error']['code']=='TASK_ID_CONFLICT'
   formal=app.send_task('shuiguang.analyze_three_views_scores',args=[request],queue='shuiguang_scores').get(timeout=30,interval=1);assert formal['error']['code']=='SCORING_REFERENCE_NOT_READY'
   checks.append({'sample':sample,'seconds_with_queue':time.monotonic()-began,'timing':timing,'idempotency':True,'task_id_conflict':True,'formal_reference_guard':True,'matches_saved_comparison':True})
   print(json.dumps(checks[-1],ensure_ascii=False),flush=True)
  assert checks[1]['timing']['resident_reuse_index']==checks[0]['timing']['resident_reuse_index']+1
  (RUNTIME/'verification.json').write_text(json.dumps({'real_celery':True,'transport':'filesystem_test_only','production_redis_tested':False,'samples':checks},ensure_ascii=False,indent=2)+'\n')
 finally:
  worker.terminate()
  try:worker.wait(timeout=30)
  except subprocess.TimeoutExpired:worker.kill();worker.wait()
  log.close()
if __name__=='__main__':main()
